import { file } from "bun";

const BACKEND_PORT = 3000;
const FRONTEND_PORT = 5173;

Bun.serve({
  port: FRONTEND_PORT,
  development: {
    hmr: true,
    console: true,
  },
  async fetch(request) {
    const url = new URL(request.url);

    // Proxy API and auth requests to the backend
    if (url.pathname.startsWith("/api/")) {
      const backendUrl = `http://localhost:${BACKEND_PORT}${url.pathname}${url.search}`;
      return await fetch(backendUrl, {
        method: request.method,
        headers: request.headers,
        body: request.body,
      });
    }

    // Serve static files (Bun will transpile .tsx on-the-fly)
    const filePath = url.pathname === "/" ? "./index.html" : `.${url.pathname}`;
    const publicFile = file(filePath);
    const exists = await publicFile.exists();
    if (exists) {
      return new Response(publicFile);
    }

    // SPA fallback
    const indexFile = file("./index.html");
    if (await indexFile.exists()) {
      return new Response(indexFile);
    }

    return new Response("Not Found", { status: 404 });
  },
});

