function createMockEventSource() {
  let onopen: (() => void) | null = null
  let onmessage: ((e: MessageEvent) => void) | null = null
  let onerror: ((e: Event) => void) | null = null
  let closeCount = 0

  class MockEventSource {
    static CONNECTING = 0
    static OPEN = 1
    static CLOSED = 2
    readyState = MockEventSource.CONNECTING

    constructor(public url: string) {
      setTimeout(() => {
        this.readyState = MockEventSource.OPEN
        onopen?.()
      }, 0)
    }

    set onopen(fn: (() => void) | null) { onopen = fn }
    get onopen() { return onopen }

    set onmessage(fn: ((e: MessageEvent) => void) | null) { onmessage = fn }
    get onmessage() { return onmessage }

    set onerror(fn: ((e: Event) => void) | null) { onerror = fn }
    get onerror() { return onerror }

    close() { closeCount++; this.readyState = MockEventSource.CLOSED }
  }

  return { MockEventSource, triggerMessage: (data: string) => onmessage?.(new MessageEvent("message", { data })), closeCount: () => closeCount }
}

describe("NotificationPage", () => {
  let mockFetch: ReturnType<typeof vi.fn>
  let esHelpers: ReturnType<typeof createMockEventSource>

  beforeEach(() => {
    mockFetch = vi.fn()
